procedure BrewReorder {
  about "Reorder kegs with low on-hand"
  policy BrewPolicy
  sheet Kegs "Kegs" { beer: Text, on_hand: Number, reorder_count: Number, partner: Text, keg_price: Money }
  trigger every day at 09:00

  let all = fetch Kegs
  let low = filter all where on_hand < 2
  for each r in low up to 3 {
    let cost = r.reorder_count * r.keg_price
    if cost > $250.00 {
      notify owner "Reorder of {r.beer} would cost {cost}, over the $250 limit."
      skip
    }
    order "{r.reorder_count} x {r.beer}" from r.partner cost cost, ask owner first timeout 12 hours else skip
    log "ordered {r.beer}"
  }
}
