procedure BrewConfirm {
  about "Confirm a private party booking and add it to the calendar"
  policy BrewPolicy
  sheet Parties "Parties" { host: Text, phone: Phone, party_at: DateTime, guests: Number, status: Text }
  calendar Patio "Patio"
  trigger when new row r in Parties

  if r.guests > 30 {
    notify owner "Over-grouped private party booking for {r.host} at {r.party_at}. Please handle it."
    stop "over-grouped goes to owner"
  }
  append Patio { title: "{r.host}", at: r.party_at, length: 3 hours }
  let m = draft sms to r.phone: "Hi {r.host}, your private party booking with the brewery is confirmed for {r.party_at}."
  let ok = request approval of m from owner timeout 1 day else stop "confirmation not approved"
  send ok
  update r set status = "confirmed"
}
