procedure LockReorder {
  about "Reorder blanks below their minimum"
  policy LockPolicy
  sheet Blanks "Blanks" { blank: Text, count: Number, minimum: Number, reorder_qty: Number, supplier: Text, unit_cost: Money }
  trigger every day at 08:00

  let all = fetch Blanks
  let low = filter all where count < minimum
  for each r in low up to 4 {
    if r.reorder_qty * r.unit_cost > $60.00 {
      notify owner "Reorder of {r.blank} would be {r.reorder_qty} x {r.unit_cost}, totaling {r.reorder_qty * r.unit_cost}. Over $60. Please review."
      skip
    }
    let cost = r.reorder_qty * r.unit_cost
    order "{r.reorder_qty} x {r.blank}" from r.supplier cost cost, ask owner first timeout 12 hours else skip
    log "ordered {r.blank}"
  }
}
```

