procedure MassageRefundRequest {
  about "Handle refund requests within limits"
  policy MassagePolicy
  sheet GiftRefunds "GiftRefunds" { card_id: Text, buyer: Text, amount: Money, bought_on: Date }
  trigger when new row r in GiftRefunds

  if days_between(r.bought_on, today()) > 90 {
    notify owner "Refund request {r.card_id} is older than 90 days."
    stop "outside refund window"
  }
  if r.amount <= $30.00 {
    refund r.amount for r.card_id reason "refund request"
  } else if r.amount <= $100.00 {
    refund r.amount for r.card_id reason "refund request", ask owner first timeout 12 hours else stop "refund not approved"
  } else {
    refund r.amount for r.card_id reason "refund request", ask owner first timeout 12 hours else stop "refund not approved"
  }
}
