  about "Nudge artists booked for tomorrow"
  policy StudioPolicy
  sheet Sessions "Sessions" { artist: Text, email: Email, session_at: DateTime, hours: Number, deposit: Money, status: Text, contract_terms: Text private }
  trigger every day at 21:00

  let all = fetch Sessions
  let due = filter all where status == "booked" and date_of(session_at) == today() + 1 day
  for each r in due up to 15 {
    let m = draft email to r.email subject "Doors open 15 minutes early": "Hi {r.artist default 'there'}, come back to the studio! Questions? Just reply."
    let ok = request approval of m from owner timeout 1 day else skip
    send ok
  }
}
```

