procedure TailorPriorityList {
  about "Tell the owner list of alterations due within 2 days"
  policy TailorPolicy
  sheet Alterations "Alterations" { ticket: Text, customer: Text, phone: Phone, due: Date, price: Money, status: Text, measurements: Text private }
  trigger every day at 08:00

  let all = fetch Alterations
  let due = filter all where status == "in-progress" and days_between(due, today()) <= 2 and days_between(due, today()) >= 0
  for each r in due up to 30 {
    notify owner "{r.ticket} due {r.due}."
  }
}
