procedure TailorChannelList {
  about "Contact the customers once they're ready"
  policy TailorPolicy
  sheet ReadyLog "ReadyLog" { ticket: Text, customer: Text, phone: Phone }
  sheet Alterations "Alterations" { ticket: Text, customer: Text, phone: Phone, due: Date, price: Money, status: Text, measurements: Text private }
  trigger when new row r in ReadyLog

  let first = draft sms to r.phone: "Hi {r.customer}, your alteration is ready! Reply with any questions."
  let ok1 = request approval of first from owner timeout 1 day else stop "first message not approved"
  send ok1
  wait 7 days
  let all = fetch Alterations
  let now_r = find all where phone == r.phone else stop "row was removed"
  if now_r.status != "picked-up" {
    let second = draft sms to now_r.phone: "Hi {now_r.customer default 'there'}, our records show a status of {now_r.status}. Reply with any questions."
    let ok2 = request approval of second from owner timeout 1 day else stop "follow-up not approved"
    send ok2
  }
}
```

