procedure TailorRefunds {
  about "Refund a refund request directly"
  policy TailorPolicy
  sheet TailorRefunds "TailorRefunds" { ticket: Text, customer: Text, price: Money }
  trigger when requested(ticket: Text)

  let all = fetch TailorRefunds
  let this = find all where ticket == ticket else stop "not found"
  refund this.price for this.id reason "refund request", ask owner first timeout 1 day else stop "refund not approved"
}
